use verus::prelude::*;

verus! {
    /// Append two vectors of f32’s, preserving order.
    fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (result: Vec<f32>)
        // no preconditions
        ensures
            // 1) length of the result is the sum of the two input lengths
            result@.len() == arr@.len() + values@.len()
        ensures
            // 2) for all i in [0 .. arr.len()), result[i] == arr[i]
            forall |i: nat| i < arr@.len() ==> result@[i] == arr@[i]
        ensures
            // 3) for all j in [0 .. values.len()), result[arr.len()+j] == values[j]
            forall |j: nat| j < values@.len()
                ==> result@[arr@.len() + j] == values@[j]
    {
        // Create an empty Vec and pre‐reserve the needed capacity
        let mut result = Vec::new();
        result.reserve(arr.len() + values.len());

        // First loop: copy all of arr into result
        let mut i = 0;
        while i < arr.len()
            invariant
                // we have processed at most arr@.len() elements
                i <= arr@.len(),
                // the current result length equals how many we've pushed
                result@.len() == i,
                // the first i elements of result match arr
                forall |k: nat| k < i ==> result@[k] == arr@[k]
            decreases arr.len() - i
        {
            result.push(arr[i]);
            i += 1;
        }

        // Second loop: append all of values into result
        let mut j = 0;
        while j < values.len()
            invariant
                // we have processed at most values@.len() elements
                j <= values@.len(),
                // result length is arr@.len() + how many of values we've pushed
                result@.len() == arr@.len() + j,
                // the prefix from arr is still preserved
                forall |k: nat| k < arr@.len() ==> result@[k] == arr@[k],
                // the next j elements of result match values
                forall |l: nat| l < j ==> result@[arr@.len() + l] == values@[l]
            decreases values.len() - j
        {
            result.push(values[j]);
            j += 1;
        }

        // At this point `j == values.len()`, so result@.len() == arr@.len() + values@.len()
        result
    }
}